package wireguard

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestParseConf(t *testing.T) {
	text := `
# Generated by the VPN server
[Interface]
PrivateKey = ` + testPrivateKey + `
Address = 10.8.0.5/24, fd00::5/64
ListenPort = 51820
DNS = 10.8.0.1
MTU = 1380
PostUp = iptables -A FORWARD -i %i -j ACCEPT

[Peer]
PublicKey = ` + testPeerKey + `
PresharedKey = ` + testPeerKey2 + `
Endpoint = vpn.example.com:51820
AllowedIPs = 10.8.0.0/24, 0.0.0.0/0, ::/0  # everything
PersistentKeepalive = 25
`
	res, err := ParseConf(text)
	require.NoError(t, err)

	cfg := res.Config
	assert.False(t, cfg.Enabled)
	assert.Equal(t, testPrivateKey, cfg.PrivateKey)
	assert.Equal(t, []string{"10.8.0.5/24", "fd00::5/64"}, cfg.Addresses)
	assert.Equal(t, 51820, cfg.ListenPort)
	require.Len(t, cfg.Peers, 1)
	assert.Equal(t, Peer{
		PublicKey:           testPeerKey,
		PresharedKey:        testPeerKey2,
		Endpoint:            "vpn.example.com:51820",
		AllowedIPs:          []string{"10.8.0.0/24"},
		PersistentKeepalive: 25,
	}, cfg.Peers[0])

	assert.Equal(t, []ImportWarning{
		{Code: "dns_ignored", Detail: "10.8.0.1"},
		{Code: "option_ignored", Detail: "MTU"},
		{Code: "option_ignored", Detail: "PostUp"},
		{Code: "default_route_removed", Detail: "0.0.0.0/0"},
		{Code: "default_route_removed", Detail: "::/0"},
	}, res.Warnings)

	cfg.Enabled = true
	require.NoError(t, cfg.Validate())
}

func TestParseConfMultiplePeersAndCase(t *testing.T) {
	text := `[interface]
privatekey=` + testPrivateKey + `
address=10.8.0.5/32
[PEER]
publickey=` + testPeerKey + `
allowedips=10.8.0.1/32
persistentkeepalive=off
[Peer]
PublicKey=` + testPeerKey2 + `
AllowedIPs=10.8.0.2/32
`
	res, err := ParseConf(text)
	require.NoError(t, err)
	require.Len(t, res.Config.Peers, 2)
	assert.Equal(t, 0, res.Config.Peers[0].PersistentKeepalive)
	assert.Equal(t, testPeerKey2, res.Config.Peers[1].PublicKey)
	assert.Empty(t, res.Warnings)
}

func TestParseConfErrors(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		errMsg string
	}{
		{"empty", "", "no [Interface] or [Peer]"},
		{"not a conf", "hello world", "key = value"},
		{"option outside section", "PrivateKey = x", "outside"},
		{"unknown section", "[Foo]", "unknown section"},
		{"unknown interface option", "[Interface]\nColour = blue", "unknown option Colour"},
		{"unknown peer option", "[Peer]\nColour = blue", "unknown option Colour"},
		{"bad listen port", "[Interface]\nListenPort = abc", "ListenPort"},
		{"bad keepalive", "[Peer]\nPersistentKeepalive = soon", "PersistentKeepalive"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := ParseConf(tt.text)
			require.Error(t, err)
			assert.Contains(t, err.Error(), tt.errMsg)
		})
	}
}
